const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const brandMark=(variant='word')=>`<svg class="brand-mark ${variant}" viewBox="${variant==='stack'?'185 340 1140 730':'185 715 1140 355'}" role="img" aria-label="Arcko Creative and Design Academy"><image href="assets/arcko-logo-original.png" width="1500" height="1500"/></svg>`;
