const icon=(n)=>`<svg class="ico" width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[n]||paths.file}"/></svg>`;
let db={students:[],leads:[],lessons:[],invoices:[],progress:[],requests:[],announcements:[],attendance:{},extras:{},branchInfo:null,teachers:[],staff:[]};let page='Dashboard',role='Admin view',leadView='board',leadStatusFilter='All',leadPriorityFilter='All',selected=null,profileTab='Overview',month=new Date().getMonth(),year=new Date().getFullYear(),query='',statusFilter='',portalTab='Home',chartTab='Revenue';const save=()=>queueSync();const money=n=>'฿'+Number(n).toLocaleString('en-US');const student=id=>db.students.find(s=>s.id==id)||{id:0,name:'(unknown student)',parent:'',phone:'',email:'',school:'',subject:'',level:'',sessions:0,total:0,coins:0,status:'',note:'',age:'',dob:''};const badge=s=>`<span class="badge ${['Unpaid','Pending','Trial booked'].includes(s)?'amber':s==='Absent'?'red':''}">${esc(s)}</span>`;const av=s=>`<span class="avatar ${s.id%3===0?'gold':s.id%2?'':'blue'}">${esc(s.name.split(' ').map(x=>x[0]).join(''))}</span>`;
const navGroups=[['WORKSPACE',[['Dashboard','home'],['Calendar','calendar'],['Reports','chart']]],['PEOPLE',[['Leads','users'],['Students','users'],['Teachers','users'],['Personnel','users']]],['LEARNING',[['Lessons','book'],['Class groups','users'],['Packages','box'],['Attendance','check'],['Student progress','star'],['Make-up requests','clock']]],['OPERATIONS',[['Invoices & payments','file'],['Recurring invoices','clock'],['Teacher payroll','coin'],['Schools & venues','pin'],['Holidays','calendar'],['Export data','file'],['Settings','settings']]]];
function sidebar(){$('#sidebar').innerHTML=`<button class="nav-close iconbtn" onclick="closeNavigation()" aria-label="Close navigation">×</button><div class="brand">${brandMark('stack')}<p>CREATIVE & DESIGN ACADEMY</p></div><div class="branch"><span class="branch-icon">${icon('home')}</span><div><strong>Arcko ${esc(branchName())}</strong><small>${branchSwitcher()}</small></div></div><nav>${visibleNav().map(([g,items])=>`<label>${g}</label>${items.map(([n,i])=>`<button class="${page===n?'active':''}" onclick="go('${n}')">${icon(i)}${n}${(n==='Make-up requests'&&db.requests.some(r=>r.status==='Pending')?'<span class="badge amber" style="margin-left:auto">'+db.requests.filter(r=>r.status==='Pending').length+'</span>':(n==='Leads'&&db.leads.length?'<span class="badge amber" style="margin-left:auto">'+db.leads.length+'</span>':''))}</button>`).join('')}`).join('')}</nav><div class="nav-bottom">Curious. Creative. Caring.</div>`}
function go(p){if(p==='Clients')p='Students';if(!allowed(p)){toast('You do not have access to that page');return}page=p;query='';statusFilter='';closeNavigation(false);render();window.scrollTo(0,0)}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.to);window.to=setTimeout(()=>$('#toast').style.display='none',3500)}function head(title,sub,action=''){return `<div class="pagehead"><div><div class="eyebrow">${role==='Admin view'?'Academy workspace':role}</div><h1>${title}</h1><p class="sub">${sub}</p></div><div class="actions">${action}</div></div>`}const btn=(t,js,cls='primary')=>`<button class="${cls}" onclick="${js}">${t}</button>`;
function table(headers,rows,empty='No records match your search.'){return `<div class="card"><div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>'<tr>'+r.map((c,i)=>`<td data-label="${esc(headers[i])}">${c}</td>`).join('')+'</tr>').join(''):`<tr><td colspan="${headers.length}" class="empty">${empty}</td></tr>`}</tbody></table></div><div class="tablefoot"><span>${rows.length} records</span><span></span></div></div>`}function filter(placeholder,opts=[]){return `<div class="card filters"><input class="search" id="search" placeholder="${placeholder}" value="${esc(query)}" oninput="query=this.value;refreshList()" aria-label="Search records">${opts.length?`<select aria-label="Filter status" onchange="statusFilter=this.value;refreshList()"><option value="">All statuses</option>${opts.map(s=>`<option ${statusFilter===s?'selected':''}>${s}</option>`).join('')}</select>`:''}<button onclick="query='';statusFilter='';render()">Reset filters</button></div>`}function refreshList(){let pos=$('#search')?.selectionStart;render();if($('#search')){$('#search').focus();$('#search').setSelectionRange(pos,pos)}}function matches(s){return JSON.stringify(s).toLowerCase().includes(query.toLowerCase())&&(!statusFilter||s.status===statusFilter)}
function stats(){const paid=db.revenueCollected;const active=db.students.filter(s=>s.status==='Active');const clients=new Set(active.map(s=>(s.parent||'').trim().toLowerCase()).filter(Boolean)).size;const upcoming=db.lessons.filter(l=>l.date>=todayStr()).length;return `<div class="stats">${[['Students',active.length,'Active learners','users'],['Upcoming lessons',upcoming,'From today onwards','book'],['Revenue collected',Number.isFinite(paid)?money(paid):'Unavailable','Paid invoices · current branch','coin'],['Active clients',clients,'Families with an active student','users']].map(([n,v,t,i])=>`<div class="card stat">${icon(i)}<small>${n}</small><strong>${v}</strong><em>${t}</em></div>`).join('')}</div>`}
function chart(){const fin=allowed('Invoices & payments');if(!fin&&chartTab==='Revenue')chartTab='Students';const rev=chartTab==='Revenue';const groups=subjects.map(sub=>{const inv=db.invoices.filter(i=>i.subject===sub);return{sub,a:rev?inv.reduce((n,i)=>n+i.amount,0):db.students.filter(s=>s.subject===sub&&s.status==='Active').length,b:rev?inv.filter(i=>i.status==='Paid').reduce((n,i)=>n+i.amount,0):0}});const max=Math.max(1,...groups.map(g=>g.a));const lab=v=>rev?money(v):v;return `<div class="card pad"><div class="cardhead"><div><h2>By programme</h2><p>${rev?'Invoiced vs collected':'Active students'}</p></div><div class="pill">${(fin?['Revenue','Students']:['Students']).map(x=>`<button class="${chartTab===x?'active':''}" onclick="chartTab='${x}';render()">${x}</button>`).join('')}</div></div><div class="chart">${groups.map(g=>`<div class="bar-group"><div class="bar" style="height:${100*g.a/max}%" title="${esc(g.sub)}: ${lab(g.a)}"></div>${rev?`<div class="bar alt" style="height:${100*g.b/max}%" title="Collected ${money(g.b)}"></div>`:''}<small>${esc(g.sub)}</small></div>`).join('')}</div><div class="legend"><span><i class="dot"></i>${rev?'Invoiced':'Active students'}</span>${rev?'<span><i class="dot b"></i>Collected</span>':''}</div></div>`}
function dashboard(){return head('A little progress. Big possibilities.',longDate(),btn('+ Schedule lesson',"lessonForm()"))+`<div class="welcome"><div><h2>Welcome back, ${esc(firstName())}.</h2><p>A thoughtful space to keep your academy moving.</p></div><div class="welcome-art"><i></i><i></i><i></i></div></div>`+stats()+`<div class="grid2">${chart()}<div class="card pad"><div class="cardhead"><h2>Needs your attention</h2><span class="badge amber">To do</span></div>${[[db.invoices.filter(i=>i.status==='Unpaid').length,'Unpaid invoices','Review balances and record payments','Invoices & payments'],[db.requests.filter(r=>r.status==='Pending').length,'Make-up requests','Find a new time to keep learning','Make-up requests'],[db.leads.length,'Families to follow up','Turn curiosity into a first class','Leads']].filter(x=>allowed(x[3])).map(([n,t,s,p])=>`<div class="todo" onclick="go('${p}')"><span class="n">${n}</span><div><strong>${t}</strong><small>${s}</small></div><span class="arrow">↗</span></div>`).join('')}</div></div><div class="card pad"><div class="cardhead"><div><h2>Today in the studio</h2><p>Make room for their next big idea.</p></div>${btn('View calendar →',"go('Calendar')",'link')}</div>${lessonTable(db.lessons.filter(l=>l.date===todayStr()))}</div>`}
function lessonTable(ls){return table(['TIME / DATE','LESSON','TEACHER','STUDENTS',''],ls.map(l=>[`${l.time}<small>${l.date}</small>`,`<b>${esc(l.subject)}</b><small>${esc(l.title)}</small>`,`${esc(l.teacher)}<small>${esc(l.room)}</small>`,`${classSize(l)} / 8`,btn('Open lesson',`lessonDetail(${l.id})`,'small')]))}
function studentList(){
 const programmes=s=>[...new Set([s.subject,...(db.classGroups||[]).filter(g=>g.student_ids.includes(s.id)).map(g=>g.subject)].filter(Boolean))];
 const arr=db.students.filter(s=>!isLeadStudent(s)&&matches({...s,programmes:programmes(s)}));
 return head('Students','Students, parent contacts and enrolments in one place.',btn('+ Add student','studentForm()'))+
 filter('Search student, student ID, parent, phone or programme…',['Active','Archived'])+
 table(['STUDENT','PARENT / GUARDIAN','CONTACT','PROGRAMMES','BALANCE','STATUS',''],arr.map(s=>[
 `<button class="link" onclick="openProfile(${s.id})">${av(s)}<b>${esc(s.name)}</b></button><small>${esc(s.studentCode||'ID assigned after saving')}</small>`,
 esc(s.parent||'Not added'),`${esc(s.phone||'—')}<small>${esc(s.email||'')}</small>`,
 programmes(s).map(p=>`<span class="badge">${esc(p)}</span>`).join(' '),
 `${s.sessions} classes left<small>${s.coins} Arcko coins</small>`,badge(s.status),btn('View profile',`openProfile(${s.id})`,'link')
 ]));
}

function openProfile(id){selected=id;page='Student profile';profileTab='Overview';render()}function profile(){const s=student(selected);return head(s.name,'Student profile · Explore their learning journey',btn('← Students',"go('Students')",'')+btn('Edit profile',`studentForm(${s.id})`)+btn('Convert to lead',`studentToLead(${s.id})`,''))+`<div class="profilegrid"><div class="card pad profilecard"><div class="avatar profilephoto">${esc(s.name.split(' ').map(n=>n[0]).join(''))}</div><h2>${esc(s.name)}</h2><p class="sub">${s.age} years · ${esc(s.level)}</p><p>${badge(s.status)}</p><div class="note"><small>STUDENT ID</small><p><strong>${esc(s.studentCode||'Assigned after saving')}</strong></p><a href="journey/" target="_blank" rel="noopener">Open student journey ↗</a></div><div class="coin"><div><small>ARCKO COINS</small><br><b>${s.coins} ✦</b></div>${btn('+ 1',`addCoin(${s.id})`,'small')}</div><div class="details"><div><small>PARENT / CLIENT</small><p>${esc(s.parent)}</p></div><div><small>CONTACT</small><p>${esc(s.phone)}<br>${esc(s.email)}</p></div><div><small>SCHOOL</small><p>${esc(s.school)}</p></div><div><small>BIRTHDAY</small><p>${esc(s.dob)}</p></div></div></div><div><div class="tabs">${['Overview','Enrolments','Attendance','Progress',...(allowed('Invoices & payments')?['Invoices']:[]),'Notes'].map(t=>`<button class="${profileTab===t?'active':''}" onclick="profileTab='${t}';render()">${t}</button>`).join('')}</div>${profileContent(s)}</div></div>`}
function profileContent(s){if(profileTab==='Overview'||profileTab==='Enrolments')return `<div class="card pad"><div class="cardhead"><h2>Learning with Arcko</h2>${badge(s.level)}</div><h3>${esc(s.subject)}</h3><p class="sub">${s.total}-session programme · 90 minutes per class</p><div class="progress"><i style="width:${s.total?100*(s.total-s.sessions)/s.total:0}%"></i></div><p class="sub">${s.total-s.sessions} completed · <b>${s.sessions} sessions remaining</b></p><div class="formfoot">${btn('Add enrolment',`enrolForm(${s.id})`)}</div></div><div class="sectiongap"><h3>Upcoming lessons</h3>${lessonTable(db.lessons.filter(l=>l.ids.includes(s.id)))}</div>`;if(profileTab==='Progress')return progressCards(s.id);if(profileTab==='Invoices')return invoiceTable(db.invoices.filter(i=>i.student===s.id));if(profileTab==='Notes')return `<div class="card pad"><h2>Teacher & admin notes</h2><div class="note">${esc(s.note||'No notes yet.')}</div>${btn('Edit notes',`noteForm(${s.id})`)}</div>`;return table(['LESSON','DATE','STATUS'],db.lessons.filter(l=>l.ids.includes(s.id)).map(l=>[esc(l.subject),l.date,badge(db.attendance[l.id+'-'+s.id]||'Not marked')]))}
function addCoin(id){student(id).coins++;save();render();toast('1 Arcko coin added')}function modal(title,sub,body,onSubmit){$('#modal').innerHTML=`<button class="close" onclick="closeModal()" aria-label="Close">×</button><h2>${title}</h2><p class="sub">${sub}</p><form id="modalform">${body}<div class="formfoot"><button type="button" onclick="closeModal()">Cancel</button><button class="primary" type="submit">Save changes</button></div></form>`;$('#modalform').onsubmit=e=>{e.preventDefault();onSubmit(Object.fromEntries(new FormData(e.target)));};$('#modal').showModal()}function closeModal(){$('#modal').close()}const field=(label,name,value='',type='text',required=true)=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></label>`;const sel=(label,name,options,value,req,onchange)=>`<label class="field">${label}<select name="${name}" ${onchange?`onchange="${onchange}"`:''}>${options.map(o=>`<option value="${esc(typeof o==='object'?o.id:o)}" ${String(typeof o==='object'?o.id:o)===String(value)?'selected':''}>${esc(typeof o==='object'?o.name:o)}</option>`).join('')}</select></label>`;const subjects=['3D Printing','Tech Toy Design','Digital Arts','Animation & Manga','Chess','Finance for Fun','Robotics','Coding','Other'];const textfield=(label,name,value='')=>`<label class="field full">${label}<textarea name="${name}">${esc(value)}</textarea></label>`;
function studentForm(id){let s=id?student(id):{};modal(id?'Edit student':'Add a new learner','Connect student details with their parent or client.',`<div class="formgrid">${field('Student name','name',s.name)}${field('Age','age',s.age||6,'number')}${field('Date of birth','dob',s.dob||'2020-01-01','date')}${sel('Level','level',['Level 1','Level 2','Level 3'],s.level)}${field('Parent / client name','parent',s.parent)}${field('Phone','phone',s.phone)}${field('Email','email',s.email,'email')}${field('School','school',s.school)}${sel('Programme','subject',subjects,s.subject)}${sel('Status','status',['Active','Archived'],s.status)}${textfield('Notes','note',s.note)}</div>`,v=>{v.age=+v.age;if(id)Object.assign(s,v);else db.students.push({...v,id:Date.now(),total:0,sessions:0,coins:0});save();closeModal();render();toast('Student profile saved')})}
function noteForm(id){modal('Student notes','Internal teacher and admin notes.',textfield('Notes','note',student(id).note),v=>{student(id).note=v.note;save();closeModal();render()})}
function enrolForm(id){
 if(!['owner','manager','admin'].includes(me.role)){toast('Ask the owner, manager or admin to confirm payment and enrol this student.');return}
 const learner=student(id);if(learner.status!=='Active'){toast('Activate the student before enrolment.');return}
 const groups=availableEnrolGroups(learner.id);if(!groups.length){toast('Create an active class group with space first.');go('Class groups');return}
 const requestId=crypto.randomUUID();let submitting=false;
 const PKGS=[{label:'8 sessions — ฿10,800',sessions:8,price:10800},{label:'12 sessions — ฿15,600',sessions:12,price:15600},{label:'16 sessions — ฿20,000',sessions:16,price:20000},{label:'Custom',sessions:0,price:0}];
 modal('Payment & enrolment','Record payment already received. No money is charged from this form.',`<div class="formgrid"><label class="field full">Class group<select id="enrol-group" name="group_id" required><option value="">Choose a class group</option>${groups.map(g=>`<option value="${esc(g.id)}">${esc(g.subject)} · ${groupDays[g.weekday]} ${groupClock(g.start_time)}–${groupClock(g.end_time)} · ${esc(g.name)}</option>`).join('')}</select></label><div class="note full" id="enrol-group-summary">Choose a group to see the teacher, venue and weekly time.</div><label class="field">Package<select name="package" onchange="updateEnrolPrice(this.value);this.form.dispatchEvent(new Event('input'))">${PKGS.map((p,i)=>`<option value="${i}">${p.label}</option>`).join('')}</select></label><label class="field">Sessions<input name="sessions" type="number" id="enrol-sessions" value="8" min="1" max="1000" required></label><label class="field">Package price (THB)<input name="base" type="number" id="enrol-base" value="10800" min="0.01" step="0.01" required></label><label class="field">Discount (THB)<input name="discount" type="number" value="0" min="0" step="0.01" required></label><div class="field"><strong id="enrol-total" aria-live="polite">Total due: ฿10,800</strong></div>${sel('Payment method','method',['','Bank transfer','Cash','PromptPay','Card'],'')}${field('Payment received on','payment_date',todayStr(),'date')}<label class="field">Amount received (THB)<input name="received" type="number" min="0.01" step="0.01" required></label>${field('Join classes on or after','from',todayStr(),'date')}<label class="checkrow full"><input type="checkbox" name="confirmed" required> I confirm full payment has been received.</label></div><p id="enrol-error" role="alert" style="color:#a53b29"></p>`,async v=>{
  if(submitting)return;
  const errorEl=$('#enrol-error');errorEl.textContent='';
  try{
   const payment=validatePaidEnrolment(v);
   const chosen=groups.find(g=>g.id===v.group_id);if(!chosen)throw Error('Choose a class group.');
   if(!v.from||v.from<todayStr())throw Error('Choose today or a future joining date.');
   submitting=true;const submit=$('#modalform button[type=submit]');submit.disabled=true;submit.textContent='Saving payment & enrolment…';
   await syncChain;if(pending||syncFailed)throw Error('Wait for other changes to finish saving, then try again.');
   const {data,error}=await sb.rpc('enrol_in_class_group',{p_request_id:requestId,p_student_id:id,p_group_id:v.group_id,p_sessions:payment.sessions,p_price:payment.price,p_discount:payment.discount,p_amount_received:payment.received,p_method:v.method,p_payment_date:v.payment_date,p_from:v.from,p_confirmed:true});
   if(error)throw Error(error.message);
   try{await loadAll()}catch{closeModal();toast('Payment and enrolment saved. Reload to see the updated records.');return}
   closeModal();render();toast('Payment recorded and student added to the class group.');
  }catch(e){errorEl.textContent=e.message||'Could not save. Please try again.'}
  finally{submitting=false;const b=$('#modalform button[type=submit]');if(b){b.disabled=false;b.textContent='Confirm payment & enrol'}}
 });
 const summary=()=>{const g=groups.find(x=>x.id===$('#enrol-group').value);$('#enrol-group-summary').textContent=g?`${g.subject} · Every ${groupDays[g.weekday]} · ${groupClock(g.start_time)}–${groupClock(g.end_time)} · ${teacherName(g.teacher_id)} · ${g.room||'Venue not set'} · ${g.student_ids.length}/8 students`:'Choose a group to see the teacher, venue and weekly time.'};$('#enrol-group').onchange=summary;
 const form=$('#modalform');form.querySelector('button[type=submit]').textContent='Confirm payment & enrol';
 form.addEventListener('input',()=>{const base=Number(form.elements.base.value),discount=Number(form.elements.discount.value);$('#enrol-total').textContent='Total due: '+money(Math.round((base-discount)*100)/100)});
}
function validatePaidEnrolment(v){
 const price=Number(v.base),discount=Number(v.discount),received=Number(v.received),sessions=Number(v.sessions);
 if(!v.confirmed)throw Error('Confirm full payment has been received before enrolling.');
 if(!Number.isInteger(sessions)||sessions<1||sessions>1000)throw Error('Enter 1–1000 sessions.');
 if(![price,discount,received].every(Number.isFinite)||price<=0||discount<0||price<=discount)throw Error('Enter a valid price and discount.');
 if(Math.round(received*100)!==Math.round((price-discount)*100))throw Error('Amount received must equal the full total due.');
 if(!['Bank transfer','Cash','PromptPay','Card'].includes(v.method))throw Error('Choose a payment method.');
 if(!v.payment_date||v.payment_date>todayStr())throw Error('Enter a payment date no later than today.');
 return {price,discount,received,sessions};
}

function availableEnrolGroups(id){return (db.classGroups||[]).filter(g=>g.active&&(g.student_ids.length<8||g.student_ids.includes(id))).sort((a,b)=>a.subject.localeCompare(b.subject)||a.weekday-b.weekday||a.start_time.localeCompare(b.start_time))}

function holidayForm(id){
  const h=id?(db.extras['Holidays']||[]).find(x=>x.id===id)||{}:{};
  modal(id?'Edit holiday':'Add a holiday','Holidays appear on the calendar for all staff.',
    `<div class="formgrid">${field('Holiday name','name',h.name||'')}${field('Date','date',h.date||todayStr(),'date')}${field('End date (optional — leave same as start for 1 day)','end',h.date||todayStr(),'date',false)}${textfield('Details (optional)','details',h.details||'')}</div>`,
    v=>{
      const start=new Date(v.date), end=new Date(v.end||v.date);
      const arr=db.extras['Holidays']||[];
      // expand multi-day holidays into individual date entries
      for(let d=new Date(start);d<=end;d.setDate(d.getDate()+1)){
        const ds=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
        arr.push({id:Date.now()+d.getDate(),name:v.name,date:ds,details:v.details||''});
      }
      db.extras['Holidays']=arr;
      save();closeModal();render();toast('Holiday added to calendar');
    });
}
function studentGroups(){
  // group upcoming lessons by subject, then show enrolled students per timeslot
  const upcoming=db.lessons.filter(l=>l.date>=todayStr()).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));
  const bySubject={};
  subjects.forEach(sub=>{
    const ls=upcoming.filter(l=>l.subject===sub);
    if(ls.length||db.students.some(s=>s.subject===sub&&s.status==='Active')) bySubject[sub]=ls;
  });
  return head('Student groups','All active learners grouped by programme, day and time.',btn('+ Schedule lesson','lessonForm()'))+
    Object.entries(bySubject).map(([sub,ls])=>`
      <div class="sectiongap"><h2>${esc(sub)}</h2>
      ${ls.length?ls.map(l=>`<div class="card pad" style="margin-bottom:12px">
        <div class="cardhead"><div><b>${l.date} · ${l.time}</b><small style="margin-left:8px">${esc(l.teacher)} · ${esc(l.room)}</small></div>
        ${btn('Edit',`lessonForm(${l.id})`,'small')}</div>
        <div style="margin-top:10px;display:flex;flex-wrap:wrap;gap:8px">${l.ids.map(i=>{const st=student(i);return `<span class="badge">${esc(st.name)}<small style="margin-left:4px;opacity:.6">${st.sessions}s</small></span>`}).join('')}</div>
      </div>`).join(''):`<div class="card empty">No upcoming lessons for ${esc(sub)}. <button class="link" onclick="lessonForm()">Schedule one.</button></div>`}
      <div style="margin-top:6px"><small class="sub">${db.students.filter(s=>s.subject===sub&&s.status==='Active').length} active students in this programme</small></div></div>`).join('');
}
function updateLessonStudents(sub){const box=document.getElementById('lesson-student-list');if(!box)return;const cur=[...box.querySelectorAll('input[type=checkbox]:checked')].map(x=>+x.name.slice(1));box.innerHTML=db.students.filter(s=>(s.status==='Active'&&s.subject===sub)||cur.includes(s.id)).map(s=>`<label class="checkrow"><input type="checkbox" name="s${s.id}" ${cur.includes(s.id)?'checked':''}>${esc(s.name)}<small style='margin-left:6px;opacity:.6'>${esc(s.subject)}</small></label>`).join('')}
function updateEnrolPrice(idx){const PKGS=[{sessions:8,price:10800},{sessions:12,price:15600},{sessions:16,price:20000},{sessions:0,price:0}];const p=PKGS[+idx];const sf=document.getElementById('enrol-sessions');const bf=document.getElementById('enrol-base');const tot=document.getElementById('enrol-total');if(sf&&bf&&tot&&p.sessions){sf.value=p.sessions;bf.value=p.price;tot.textContent='Total: ฿'+p.price.toLocaleString('en-US')}}
function leads(){
  const lv=leadView;
  const activeSt=['New inquiry','Trial booked','Contacted','Follow up','Not interested'];
  const hdr=head('Leads','Make every first conversation count.',`${btn('+ Add lead','leadForm()')}<div class="pill" style="margin-left:8px">${btn('List',"leadView='list';render()",lv==='list'?'active':'small')}${btn('Kanban board',"leadView='board';render()",lv==='board'?'active':'small')}</div>`);
  if(lv==='board') return hdr+filter('Search family, child or subject…')+leadKanban();
  const counts={};[...activeSt,'All'].forEach(st=>counts[st]=st==='All'?db.leads.filter(l=>l.status!=='Closed lost').length:db.leads.filter(l=>l.status===st).length);
  const sf=leadStatusFilter;
  const pf=leadPriorityFilter;
  const PRIOS=['All','High','Medium','Low'];
  const STATS=['All',...activeSt];
  const phdr=`<select onchange="leadPriorityFilter=this.value;render()" style="font-size:11px;border:none;background:transparent;font-weight:600;cursor:pointer">${PRIOS.map(p=>`<option ${pf===p?'selected':''}>${p}</option>`).join('')}</select>`;
  const shdr=`<select onchange="leadStatusFilter=this.value;render()" style="font-size:11px;border:none;background:transparent;font-weight:600;cursor:pointer">${STATS.map(p=>`<option ${sf===p?'selected':''}>${p}</option>`).join('')}</select>`;
  const visible=db.leads.filter(l=>l.status!=='Closed lost'&&(sf==='All'||l.status===sf)&&(pf==='All'||l.priority===pf)&&matches(l));
  const closedLost=db.leads.filter(l=>l.status==='Closed lost');
  return hdr
    +`<div class="pill" style="margin-bottom:14px">${['All',...activeSt].map(st=>`<button class="${(leadStatusFilter)===st?'active':''}" onclick="leadStatusFilter='${st}';render()">${esc(st)} <span class="badge" style="margin-left:4px">${counts[st]||0}</span></button>`).join('')}</div>`
    +filter('Search family, child or subject…')
    +table(['PARENT / LEAD','CHILD','INTEREST','SOURCE',phdr,shdr,''],visible.map(l=>[
      `<b>${esc(l.name)}</b><small>${esc(l.phone)}</small>`,
      `${esc(l.child||'')}<small>${l.age?l.age+' yrs':''}</small>`,
      (l.subjects&&l.subjects.length?l.subjects.map(x=>`<span class="badge">${esc(x)}</span>`).join(' '):esc(l.subject||'')),
      esc(l.source||'—'),
      l.priority?`<span class="badge ${l.priority==='High'?'red':l.priority==='Low'?'':'amber'}">${esc(l.priority)}</span>`:'—',
      badge(l.status),
      `${btn('Edit',`leadEdit(${l.id})`,'small')} ${l.status==='Trial booked'?btn('+ Trial class',`leadTrialClass(${l.id})`,'small'):''} ${btn('Convert →',`convertLead(${l.id})`,'small')}`
    ]))
    +(closedLost.length?`<div class="sectiongap"><h2 style="color:var(--sub);font-size:14px">CLOSED LOST (${closedLost.length})</h2>`
      +table(['PARENT / LEAD','CHILD','INTEREST','DATE',''],closedLost.map(l=>[
        `<b>${esc(l.name)}</b><small>${esc(l.phone)}</small>`,
        `${esc(l.child||'')}<small>${l.age?l.age+' yrs':''}</small>`,
        (l.subjects&&l.subjects.length?l.subjects.map(x=>`<span class="badge">${esc(x)}</span>`).join(' '):esc(l.subject||'')),
        esc(l.created_at?l.created_at.slice(0,10):'—'),
        btn('Reopen',`reopenLead(${l.id})`,'small')
      ]))+'</div>':'');
}

let leadStage='New inquiry';
const leadStages=['New inquiry','Contacted','Trial booked','Follow up','Not interested'];
function selectLeadStage(stage){leadStage=stage;render()}
function leadKanban(){
 const visible=db.leads.filter(matches),active=visible.filter(l=>l.status!=='Closed lost');
 const count=st=>visible.filter(l=>l.status===st).length;
 return `<section class="pipeline-summary"><div><strong>${active.length}</strong> leads in your pipeline</div><span>Open a card for details · Drag to move on desktop</span></section>
 <nav class="stage-tabs" aria-label="Lead stages">${leadStages.map(st=>`<button aria-pressed="${leadStage===st}" onclick="selectLeadStage('${st}')">${st}<span>${count(st)}</span></button>`).join('')}</nav>
 <div class="kanban">${leadStages.map((st,i)=>`<section class="kanban-col ${st===leadStage?'selected-stage':''}" style="--stage-color:${['#489cf0','#8b7cce','#80be2c','#e0a135','#94a3b8'][i]}" ondragover="event.preventDefault();this.classList.add('drop-target')" ondragleave="if(!this.contains(event.relatedTarget))this.classList.remove('drop-target')" ondrop="this.classList.remove('drop-target');leadDrop(event,'${st}')"><header class="kanban-head"><h2>${st}</h2><span>${count(st)}</span></header><div class="kanban-cards">${visible.filter(l=>l.status===st).map(l=>leadCard(l)).join('')||'<div class="stage-empty">No leads here yet.<small>Move a lead here as they progress.</small></div>'}</div></section>`).join('')}</div>
 <details class="closed-leads"><summary>Closed lost <span>${count('Closed lost')}</span></summary><div>${visible.filter(l=>l.status==='Closed lost').map(l=>`<div class="closed-row"><span><b>${esc(l.child||l.name)}</b><small>${esc(l.name)}</small></span>${btn('Reopen',`reopenLead(${l.id})`,'small')}</div>`).join('')||'<p>No closed leads.</p>'}</div></details>`;
}
function leadCard(l){
 const bookings=db.lessons.filter(x=>(x.trials||[]).some(t=>t.leadId===l.id)&&x.date>=todayStr()).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));
 const next=bookings[0];
 return `<article class="kanban-card" draggable="true" ondragstart="window._dragLead=${l.id};event.dataTransfer.setData('text/plain','${l.id}')" ondragend="window._dragLead=null;document.querySelectorAll('.drop-target').forEach(x=>x.classList.remove('drop-target'))"><button class="lead-card-open" onclick="leadDetails(${l.id})" aria-label="Open ${esc(l.child||l.name)}"><span class="lead-card-top"><span class="lead-initial">${esc((l.child||l.name||'?')[0])}</span>${l.priority==='High'?'<span class="priority-high">High priority</span>':''}<span class="lead-chevron">↗</span></span><strong>${esc(l.child||l.name)}</strong><span class="lead-parent">${esc(l.name)}${l.age?' · '+esc(l.age)+' yrs':''}</span><span class="lead-subjects">${(l.subjects?.length?l.subjects:[l.subject]).filter(Boolean).map(x=>`<span>${esc(x)}</span>`).join('')}</span>${next?`<span class="trial-booking">Trial · ${esc(next.date)} · ${esc(next.time)}</span>`:''}</button><div class="lead-card-footer">${l.status==='Trial booked'?btn(next?'Manage trial':'Book trial class',`leadTrialClass(${l.id})`,'lead-primary'):btn('View details',`leadDetails(${l.id})`,'lead-secondary')}<button class="lead-move" onclick="leadMoveForm(${l.id})" aria-label="Move ${esc(l.child||l.name)} to another stage">Move →</button></div></article>`;
}
function leadMoveForm(id){const l=db.leads.find(x=>x.id===id);if(!l)return;modal('Move lead',esc(l.child||l.name),sel('Pipeline stage','stage',[...leadStages,'Closed lost'],l.status),v=>{moveLead(id,v.stage);leadStage=v.stage==='Closed lost'?leadStage:v.stage;closeModal();render();toast('Moved to '+v.stage)})}
function leadDetails(id){const l=db.leads.find(x=>x.id===id);if(!l)return;$('#modal').innerHTML=`<button class="close" onclick="closeModal()" aria-label="Close">×</button><div class="eyebrow">${esc(l.status)}</div><h2>${esc(l.child||l.name)}</h2><p class="sub">${esc(l.name)}${l.age?' · '+esc(l.age)+' years old':''}</p><dl class="lead-detail-grid"><div><dt>Phone</dt><dd>${esc(l.phone||'Not added')}</dd></div><div><dt>Priority</dt><dd>${esc(l.priority||'Medium')}</dd></div><div><dt>Interested in</dt><dd>${esc((l.subjects||[l.subject]).filter(Boolean).join(', '))}</dd></div><div><dt>Source</dt><dd>${esc(l.source||'Not added')}</dd></div></dl><p class="lead-notes">${esc(l.note||'No notes yet.')}</p><div class="lead-detail-actions">${btn('Edit details',`closeModal();leadEdit(${id})`,'')}${btn('Move stage',`closeModal();leadMoveForm(${id})`,'')}${l.status==='Trial booked'?btn('Book trial class',`closeModal();leadTrialClass(${id})`):''}${btn('Convert to client',`if(confirm('Convert this lead to a client?')){closeModal();convertLead(${id})}`)}</div>`;$('#modal').showModal()}

function moveLead(id,status){const l=db.leads.find(x=>x.id===id);if(l){l.status=status;save();render()}}
function leadDrop(e,status){
  e.preventDefault();
  const id=window._dragLead; if(!id)return;
  const l=db.leads.find(l=>l.id===id); if(!l)return;
  l.status=status; save(); render(); window._dragLead=null;
}
function closeLead(id){
  const l=db.leads.find(l=>l.id===id); if(!l)return;
  l.status='Closed lost'; save(); render(); toast('Lead moved to Closed lost');
}
function reopenLead(id){
  const l=db.leads.find(l=>l.id===id); if(!l)return;
  l.status='Follow up'; save(); render(); toast('Lead reopened');
}
function leadTrialClass(id){
  const l=db.leads.find(l=>l.id===id); if(!l)return;
  const subs=l.subjects&&l.subjects.length?l.subjects:[l.subject].filter(Boolean);
  const upcoming=db.lessons.filter(x=>x.date>=todayStr()&&(subs.length===0||subs.includes(x.subject)));
  if(!upcoming.length){toast('No upcoming lessons match this lead\'s subjects. Schedule one first.');return;}
  modal('Add to trial class','Choose a lesson for '+(l.child||l.name)+' to trial as a guest.',
    `<div class="formgrid"><label class="field full">Lesson<select name="lesson_id">${upcoming.map(x=>`<option value="${x.id}">${x.date} ${x.time} · ${esc(x.subject)} · ${esc(x.teacher)}</option>`).join('')}</select></label></div>`,
    v=>{
      const les=db.lessons.find(x=>x.id===+v.lesson_id); if(!les)return;
      les.trials ||= [];
      if(les.trials.some(t=>t.leadId===id))return toast('This lead is already booked in this class');
      if(classSize(les)>=8)return toast('This class is full (max 8 students)');
      if(db.lessons.some(x=>x.id!==les.id&&x.date===les.date&&x.time===les.time&&(x.trials||[]).some(t=>t.leadId===id)))return toast('This lead already has a trial at that time');
      les.trials.push({leadId:id,name:l.child||l.name,status:'Not marked'});
      save();closeModal();render();toast((l.child||l.name)+' added as trial guest to '+les.date+' '+les.time);
    });
}

function leadForm(){modal('New inquiry','Record a family’s interest.',`<div class="formgrid">${field('Parent name','name')}${field('Child name','child')}${field('Phone','phone')}${field('Age','age',6,'number')}${sel('Interested programme','subject',subjects,'')}<label class="field full">Also interested in<div class="checkrow-group">${subjects.map(sub=>`<label class="checkrow"><input type="checkbox" name="sub_${sub.replace(/\s+/g,'_')}" value="${esc(sub)}">${esc(sub)}</label>`).join('')}</div></label>${sel('Source','source',['Instagram','LINE','Facebook','Referral','Walk-in','Website','Event','Other'],'')}${sel('Priority','priority',['High','Medium','Low'],'Medium')}${sel('Status','status',['New inquiry','Trial booked','Contacted','Follow up','Not interested','Closed lost'])}${textfield('Notes','note','')}</div>`,v=>{const extraSubs=subjects.filter(sub=>v['sub_'+sub.replace(/\s+/g,'_')]);const allSubs=[...new Set([v.subject,...extraSubs])].filter(Boolean);db.leads.push({...v,id:Date.now(),age:+v.age,subjects:allSubs,note:v.note||'',source:v.source||'',priority:v.priority||'Medium'});save();closeModal();render();toast('Lead added')})}function leadEdit(id){let l=db.leads.find(l=>l.id===id);modal('Edit lead','Update status, add a note or change subjects.',`<div class="formgrid">${field('Parent name','name',l.name)}${field('Child name','child',l.child||'')}${field('Phone','phone',l.phone||'')}${field('Age','age',l.age||6,'number')}${sel('Primary programme','subject',subjects,l.subject)}<label class="field full">Also interested in<div class="checkrow-group">${subjects.map(sub=>`<label class="checkrow"><input type="checkbox" name="sub_${sub.replace(/\s+/g,'_')}" value="${esc(sub)}" ${(l.subjects||[]).includes(sub)?'checked':''}>${esc(sub)}</label>`).join('')}</div></label>${sel('Source','source',['Instagram','LINE','Facebook','Referral','Walk-in','Website','Event','Other'],l.source||'')}${sel('Priority','priority',['High','Medium','Low'],l.priority||'Medium')}${sel('Status','status',['New inquiry','Trial booked','Contacted','Follow up','Not interested','Closed lost'],l.status)}${textfield('Notes','note',l.note||'')}</div>`,v=>{const extraSubs=subjects.filter(sub=>v['sub_'+sub.replace(/\s+/g,'_')]);const allSubs=[...new Set([v.subject,...extraSubs])].filter(Boolean);Object.assign(l,{...v,age:+v.age,subjects:allSubs,note:v.note||'',source:v.source||'',priority:v.priority||'Medium'});save();closeModal();render();toast('Lead updated')})}
function leadLinks(){return db.extras['Lead links'] ||= []}
function linkedStudent(l){const link=leadLinks().find(x=>Number(x.name)===l.id);if(link)return db.students.find(s=>s.id===Number(link.details));const candidates=db.students.filter(s=>s.status==='Archived'&&s.name===l.child&&s.parent===l.name&&s.phone===l.phone&&l.note?.startsWith('Converted back from student.'));return candidates.length===1?candidates[0]:null}
function isLeadStudent(s){return db.leads.some(l=>linkedStudent(l)?.id===s.id)}
function studentToLead(id){
 const s=db.students.find(x=>x.id===id);if(!s)return;
 if(isLeadStudent(s))return go('Leads');
 if(!confirm('Move '+s.name+' back to Leads? Lesson history and invoices will be retained.'))return;
 const lid=Date.now();db.leads.push({id:lid,name:s.parent||s.name,child:s.name,age:s.age||'',subject:s.subject,subjects:[s.subject],phone:s.phone||'',status:'Follow up',note:'Converted back from student. '+(s.note||''),source:'',priority:'Medium'});
 leadLinks().push({id:lid+1,name:String(lid),details:String(id)});s.status='Archived';save();go('Leads');toast(s.name+' moved back to Leads');
}
function convertLead(id){
 const l=db.leads.find(x=>x.id===id);if(!l)return;
 let s=linkedStudent(l);
 if(!s){s={id:Date.now(),name:l.child||l.name,age:l.age,parent:l.name,phone:l.phone,email:'',school:'',subject:l.subject,status:'Active',level:l.age<7?'Level 1':'Level 2',sessions:0,total:0,coins:0,note:l.note||'',dob:''};db.students.push(s)}
 s.status='Active';db.leads=db.leads.filter(x=>x.id!==id);db.extras['Lead links']=leadLinks().filter(x=>Number(x.name)!==id);
 save();toast('Lead converted to client and student');openProfile(s.id);
}
const classSize=l=>(l.ids||[]).length+(l.trials||[]).length;
function trialRoster(l){return (l.trials||[]).map(t=>`<div class="todo"><div><strong>${esc(t.name)}</strong><small>Trial guest</small></div><select aria-label="Trial attendance for ${esc(t.name)}" onchange="trialAttendance(${l.id},${t.leadId},this.value)">${['Not marked','Present','Absent','Excused'].map(st=>`<option ${st===t.status?'selected':''}>${st}</option>`).join('')}</select>${role==='Admin view'?btn('Remove',`removeTrial(${l.id},${t.leadId})`,'small'):''}</div>`).join('')}
function trialAttendance(lid,id,status){const t=db.lessons.find(l=>l.id===lid)?.trials?.find(t=>t.leadId===id);if(t){t.status=status;save()}}
function removeTrial(lid,id){const l=db.lessons.find(l=>l.id===lid);if(!l)return;l.trials=(l.trials||[]).filter(t=>t.leadId!==id);save();lessonDetail(lid)}
function calendar(){
  const cv=window._calView||'month';
  if(cv==='day') return calendarDay();
  if(cv==='week') return calendarWeek();
  let date=new Date(year,month,1),start=(date.getDay()+6)%7,days=new Date(year,month+1,0).getDate();
  return head('Calendar','A clear view of every creative moment.',btn('+ Schedule lesson',"lessonForm()"))
  +`<div class="pill" style="margin-bottom:12px"><button class="${cv==='month'?'active':''}" onclick="window._calView='month';render()">Month</button><button class="${cv==='week'?'active':''}" onclick="window._calView='week';render()">Week</button><button class="${cv==='day'?'active':''}" onclick="window._calView='day';render()">Day</button></div>`
  +`<div class="card"><div class="monthbar"><div class="actions">${btn('‹',"changeMonth(-1)",'small')}<h2>${date.toLocaleString('en-US',{month:'long',year:'numeric'})}</h2>${btn('›',"changeMonth(1)",'small')}</div>${btn('Today',"month=new Date().getMonth();year=new Date().getFullYear();render()",'small')}</div><div class="tablewrap calendar-month-grid"><div class="schedule">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="dayhead">${d}</div>`).join('')}${Array.from({length:Math.ceil((start+days)/7)*7},(_,i)=>{let d=i-start+1,ds=`${year}-${String(month+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;return `<div class="day ${ds===todayStr()?'today':''}">${d>0&&d<=days?`<span>${d}</span>${db.lessons.filter(l=>l.date===ds).map(l=>`<button class="event ${l.subject==='Digital Arts'?'blue':l.subject==='Tech Toy Design'?'gold':l.subject==='Animation & Manga'?'purple':l.subject==='Robotics'?'gold':l.subject==='Coding'?'blue':l.subject==='Chess'?'amber':''}" onclick="lessonDetail(${l.id})">${l.time} · ${esc(l.subject)}<br>${esc(l.teacher)}</button>`).join('')+(db.extras['Holidays']||[]).filter(h=>h.date===ds).map(h=>`<div class="event red" title="Holiday: ${esc(h.name)}">${icon('calendar')} ${esc(h.name)}</div>`).join('')}`:''}</div>`}).join('')}</div></div>${mobileAgenda()}</div></div><div class="legend"><span><i class=\"dot\"></i>3D Printing</span><span><i class=\"dot b\"></i>Digital Arts</span><span>● Tech Toy Design</span><span>◆ Animation</span><span>◇ Manga</span><span><i class=\"dot\" style=\"background:#e53e3e\"></i>Holiday</span></div>`
}
function calendarDay(){
  const d=window._calDay||todayStr();
  const lessons=db.lessons.filter(l=>l.date===d).sort((a,b)=>a.time.localeCompare(b.time));
  const holidays=(db.extras['Holidays']||[]).filter(h=>h.date===d);
  const dt=new Date(d+'T00:00:00');
  const fmt=dt.toLocaleDateString('en-US',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
  return head('Calendar','A clear view of every creative moment.',btn('+ Schedule lesson',"lessonForm()"))
    +`<div class="pill" style="margin-bottom:12px"><button onclick="window._calView='month';render()">Month</button><button onclick="window._calView='week';render()">Week</button><button class="active">Day</button></div>`
    +`<div class="card pad"><div class="monthbar"><div class="actions">${btn('‹',"prevDay()",'small')}<h2>${fmt}</h2>${btn('›',"nextDay()",'small')}</div>${btn('Today',"window._calDay=todayStr();render()",'small')}</div>`
    +(holidays.map(h=>`<div class="event red" style="margin:8px 0">${icon('calendar')} Holiday: ${esc(h.name)}</div>`).join(''))
    +(lessons.length?lessons.map(l=>`<div class="todo" onclick="lessonDetail(${l.id})"><span class="branch-icon">${icon('book')}</span><div><strong>${esc(l.subject)} · ${l.time}</strong><small>${esc(l.title)} · ${esc(l.teacher)} · ${esc(l.room)||'No venue'} · ${classSize(l)} students</small></div><span class="arrow">→</span></div>`).join('')
    :`<div class="empty">No lessons on this day. <button class="link" onclick="lessonForm()">Schedule one.</button></div>`)
    +`</div>`;
}
function calendarWeek(){
  const base=window._calDay||todayStr();
  const bd=new Date(base+'T00:00:00');
  const dow=(bd.getDay()+6)%7;
  const mon=new Date(bd); mon.setDate(bd.getDate()-dow);
  const days=Array.from({length:7},(_,i)=>{const d=new Date(mon);d.setDate(mon.getDate()+i);return ymd(d)});
  const fmt=d=>new Date(d+'T00:00:00').toLocaleDateString('en-US',{weekday:'short',day:'numeric',month:'short'});
  return head('Calendar','A clear view of every creative moment.',btn('+ Schedule lesson',"lessonForm()"))
    +`<div class="pill" style="margin-bottom:12px"><button onclick="window._calView='month';render()">Month</button><button class="active">Week</button><button onclick="window._calView='day';window._calDay=todayStr();render()">Day</button></div>`
    +`<div class="card"><div class="monthbar"><div class="actions">${btn('‹',"prevWeek()",'small')}<h2>Week of ${fmt(days[0])}</h2>${btn('›',"nextWeek()",'small')}</div>${btn('Today',"window._calDay=todayStr();render()",'small')}</div>`
    +`<div class="tablewrap"><table class="week-grid"><thead><tr>${days.map(d=>`<th class="${d===todayStr()?'today':''}">${fmt(d)}</th>`).join('')}</tr></thead><tbody><tr>${days.map(d=>{
      const ls=db.lessons.filter(l=>l.date===d).sort((a,b)=>a.time.localeCompare(b.time));
      const hs=(db.extras['Holidays']||[]).filter(h=>h.date===d);
      return `<td>${hs.map(h=>`<div class="event red">${esc(h.name)}</div>`).join('')}${ls.map(l=>`<button class="event ${l.subject==='Digital Arts'?'blue':l.subject==='Animation & Manga'?'purple':l.subject==='Robotics'?'gold':l.subject==='Coding'?'blue':l.subject==='Chess'?'amber':''}" onclick="window._calView='day';window._calDay='${d}';render()">${l.time}<br>${esc(l.subject)}<br><small>${esc(l.teacher)}</small></button>`).join('')||'<div style="height:40px"></div>'}</td>`
    }).join('')}</tr></tbody></table></div></div>`;
}
function prevDay(){const d=new Date((window._calDay||todayStr())+'T00:00:00');d.setDate(d.getDate()-1);window._calDay=ymd(d);render()}
function nextDay(){const d=new Date((window._calDay||todayStr())+'T00:00:00');d.setDate(d.getDate()+1);window._calDay=ymd(d);render()}
function prevWeek(){const d=new Date((window._calDay||todayStr())+'T00:00:00');d.setDate(d.getDate()-7);window._calDay=ymd(d);render()}
function nextWeek(){const d=new Date((window._calDay||todayStr())+'T00:00:00');d.setDate(d.getDate()+7);window._calDay=ymd(d);render()}
function changeMonth(n){month+=n;if(month>11){month=0;year++}if(month<0){month=11;year--}render()}
function lessonForm(id){let l=db.lessons.find(l=>l.id===id)||{};modal(id?'Reschedule lesson':'Schedule a lesson','Choose a time, teacher and students. Up to 8 children per class.',`<div class="formgrid">${sel('Programme','subject',subjects,l.subject,true,'updateLessonStudents(this.value)')}${field('Lesson title','title',l.title||'Creative discovery')}${field('Date','date',l.date||datePlus(1),'date')}${field('Start time','time',l.time||'10:00','time')}${field('End time','end_time',l.end_time||groupDefaultEnd(l.time||'10:00'),'time')}${sel('Teacher','teacher_id',teacherOptions(),l.teacher_id||'')}${field('Venue','room',l.room||'','text',false)}${(!id)?sel('Repeat','repeat',['No repeat','Every week','Every 2 weeks','Every month'],'No repeat'):''}${(!id)?field('Number of occurrences (if repeating)','occurrences',8,'number',false):''}<div class="field full">Students${db.students.filter(s=>(s.status==='Active'&&s.subject===(l.subject||subjects[0]))||l.ids?.includes(s.id)).map(s=>`<label class="checkrow"><input type="checkbox" name="s${s.id}" ${l.ids?.includes(s.id)?'checked':''}>${esc(s.name)}<small style='margin-left:6px;opacity:.6'>${esc(s.subject)}</small></label>`).join('')}</div></div>`,v=>{let ids=db.students.filter(s=>v['s'+s.id]).map(s=>s.id);if(ids.length+(l?.trials||[]).length>8)return toast('Choose 1–8 students');
const existingIds=typeof id!=='undefined'?(db.lessons.find(l=>l.id===id)?.ids||[]):[];
const newIds=ids.filter(sid=>!existingIds.includes(sid));
const clash=newIds.find(sid=>db.lessons.some(x=>x.id!==id&&x.date===v.date&&x.time===v.time&&(x.ids||[]).includes(sid)));
if(clash)return toast(student(clash).name+' is already in another class at that time. Pick a different time.');
const tclash=v.teacher_id&&v.teacher_id!==(db.lessons.find(l=>l.id===id)?.teacher_id)&&db.lessons.find(x=>x.id!==id&&x.date===v.date&&x.time===v.time&&x.teacher_id===v.teacher_id);
if(tclash)return toast(teacherName(v.teacher_id)+' already has a class at '+v.date+' '+v.time+'. Assign a different teacher.');if(!v.end_time||v.end_time<=v.time)return toast('End time must be after start time');let vals={subject:v.subject,title:v.title,date:v.date,time:v.time,end_time:v.end_time,teacher:teacherName(v.teacher_id),teacher_id:v.teacher_id||null,room:v.room||'',ids};if(id){(l.ids||[]).filter(x=>!ids.includes(x)).forEach(sid=>{const k=l.id+'-'+sid;if(db.attendance[k]==='Present')student(sid).sessions++;delete db.attendance[k]});Object.assign(l,vals)}else{
  const repeat=v.repeat||'No repeat';
  const occ=Math.min(52,Math.max(1,+v.occurrences||1));
  const repeatDays=repeat==='Every week'?7:repeat==='Every 2 weeks'?14:repeat==='Every month'?30:0;
  db.lessons.push({...vals,id:Date.now()});
  if(repeatDays>0&&occ>1){
    const [y,mo,d]=vals.date.split('-').map(Number);
    let base=new Date(y,mo-1,d);
    for(let i=1;i<occ;i++){
      base=new Date(base.getTime()+repeatDays*86400000);
      const nd=`${base.getFullYear()}-${String(base.getMonth()+1).padStart(2,'0')}-${String(base.getDate()).padStart(2,'0')}`;
      db.lessons.push({...vals,id:Date.now()+i,date:nd});
    }
    toast(`${occ} lessons scheduled (${repeat.toLowerCase()})`);
  }else toast('Lesson saved to calendar');
}save();closeModal();render()})}
function lessonDetail(id){let l=db.lessons.find(l=>l.id===id);$('#modal').innerHTML=`<button class="close" onclick="closeModal()" aria-label="Close">×</button><div class="eyebrow">${esc(l.subject)}</div><h2>${esc(l.title)}</h2><p class="sub">${l.date} · ${l.time} · 90 minutes<br>${esc(l.teacher)} · ${esc(l.room)}</p>${l.end_time?`<p class="sub">Ends ${esc(l.end_time.slice(0,5))}</p>`:''}<h3>Class attendance</h3>${trialRoster(l)}${l.ids.map(i=>{let s=student(i),key=l.id+'-'+i;return `<div class="todo">${av(s)}<div><strong>${esc(s.name)}</strong><small>${s.sessions} sessions remaining</small></div><select style="margin-left:auto" aria-label="Attendance for ${esc(s.name)}" onchange="markAttendance(${id},${i},this.value)">${['Not marked','Present','Absent','Excused'].map(x=>`<option ${db.attendance[key]===x?'selected':''}>${x}</option>`).join('')}</select></div>`}).join('')}<div class="formfoot">${btn('Add progress note',`closeModal();progressForm(${l.ids[0]})`,'')}${role==='Admin view'?btn('Reschedule',`closeModal();lessonForm(${id})`)+''+btn('Edit students',`editLessonStudents(${id})`,''):''}${role==='Admin view'?btn('Cancel lesson',`cancelLesson(${id})`,'danger'):''}
</div>`;$('#modal').showModal()}
function editLessonStudents(id){
  const l=db.lessons.find(l=>l.id===id);
  modal('Edit class roster','Add or remove students from this lesson.',
    `<div class="field full">Students<div id="lesson-student-list">${db.students.filter(s=>s.status==='Active'||l.ids?.includes(s.id)).map(s=>`<label class="checkrow"><input type="checkbox" name="s${s.id}" ${l.ids?.includes(s.id)?'checked':''}>${esc(s.name)}<small style='margin-left:6px;opacity:.6'>${esc(s.subject)}</small></label>`).join('')}</div></div>`,
    v=>{
      const ids=db.students.filter(s=>v['s'+s.id]).map(s=>s.id);
      if(ids.length+(l?.trials||[]).length>8)return toast('Choose 1–8 students');
      const clash=ids.filter(sid=>!l.ids.includes(sid)).find(sid=>db.lessons.some(x=>x.id!==id&&x.date===l.date&&x.time===l.time&&(x.ids||[]).includes(sid)));
      if(clash)return toast(student(clash).name+' is already in another class at that time');
      (l.ids||[]).filter(x=>!ids.includes(x)).forEach(sid=>{const k=l.id+'-'+sid;if(db.attendance[k]==='Present')student(sid).sessions++;delete db.attendance[k]});
      l.ids=ids;save();closeModal();render();toast('Roster updated');
    });
}
function cancelLesson(id){
  if(!confirm('Cancel this lesson? Attendance records will be removed.'))return;
  const l=db.lessons.find(l=>l.id===id);
  (l.ids||[]).forEach(sid=>{const k=l.id+'-'+sid;if(db.attendance[k]==='Present')student(sid).sessions++;delete db.attendance[k]});
  db.lessons=db.lessons.filter(l=>l.id!==id);
  save();closeModal();render();toast('Lesson cancelled');
}
function markAttendance(l,s,value){let key=l+'-'+s,prev=db.attendance[key],st=student(s);if(value==='Present'&&prev!=='Present'){if(st.sessions<1){toast('No sessions remaining. Add a package first.');lessonDetailRefresh(l);return}st.sessions--}if(prev==='Present'&&value!=='Present')st.sessions++;db.attendance[key]=value;save();toast('Attendance saved; session balance updated');render()}function lessonDetailRefresh(id){closeModal();lessonDetail(id)}
function invoices(){return head('Invoices & payments','Keep payments clear, organised and connected.',btn('+ Create invoice',"invoiceForm()"))+`<div class="stats">${[['Total invoiced',db.invoices.reduce((s,i)=>s+i.amount,0)],['Collected',db.invoices.filter(i=>i.status==='Paid').reduce((s,i)=>s+i.amount,0)],['Outstanding',db.invoices.filter(i=>i.status==='Unpaid').reduce((s,i)=>s+i.amount,0)]].map(([l,v])=>`<div class="card stat"><small>${l}</small><strong>${money(v)}</strong></div>`).join('')}</div>`+filter('Search invoice, programme or amount…',['Unpaid','Paid'])+invoiceTable(db.invoices.filter(i=>matches({...i,name:student(i.student).name})))}
function invoiceTable(arr){return table(['INVOICE','STUDENT / CLIENT','PROGRAMME','AMOUNT','STATUS',''],arr.map(i=>[`<button class="link" onclick="invoiceDetail(${i.id})">INV-${i.id}</button><small>Due ${i.due}</small>`,`${esc(student(i.student).name)}<small>${esc(student(i.student).parent)}</small>`,esc(i.subject),money(i.amount),badge(i.status),btn(i.status==='Paid'?'View receipt':'Record payment',`invoiceDetail(${i.id})`,'small')]))}
function invoiceForm(){modal('Create invoice','No email or payment request is sent from this system.',`<div class="formgrid">${sel('Student','student',db.students)}${sel('Programme','subject',subjects)}${field('Package price (THB)','base',10800,'number')}${field('Discount (THB)','discount',0,'number')}${field('Additional fee (THB)','fee',0,'number')}${field('Due date','due',datePlus(7),'date')}</div>`,v=>{let amount=+v.base-+v.discount + +v.fee;if(amount<0)return toast('Total cannot be negative');db.invoices.push({id:Date.now(),student:+v.student,subject:v.subject,amount,status:'Unpaid',date:todayStr(),due:v.due});save();closeModal();render();toast('Invoice created')})}
function invoiceDetail(id){let i=db.invoices.find(i=>i.id===id),s=student(i.student);$('#modal').innerHTML=`<button class="close" onclick="closeModal()">×</button>${brandMark()}<p class="sub">Creative & Design Academy · ${i.status==='Paid'?'Receipt':'Invoice'}</p><div class="cardhead"><h2>INV-${i.id}</h2>${badge(i.status)}</div><p><b>${esc(s.parent)}</b><br>${esc(s.name)} · ${esc(s.email)}</p><p class="sub">Issued ${i.date} · Due ${i.due}</p><div class="note">${esc(i.subject)} · Course package</div><div class="invoice-total">Total amount<br><strong>${money(i.amount)}</strong></div>${i.status==='Unpaid'?`<label class="field">Payment method<select id="paymethod"><option>Bank transfer</option><option>Cash</option><option>PromptPay</option><option>Card</option></select></label><div class="note">This records a payment you have already received. No money is charged here.</div><div class="formfoot">${btn('Confirm payment',`payInvoice(${id})`)}</div>`:`<p class="note">Payment recorded${i.method?' via '+esc(i.method):''}. Thank you!</p><div class="formfoot">${btn('Close',"closeModal()")}</div>`}`;$('#modal').showModal()}
