function people(){const teacher=page==='Teachers';const list=teacher?db.teachers:db.staff;return head(page,teacher?'The people guiding every creative discovery.':'Your team and what each role can do.',teacher?(me.role==='owner'?btn('+ Add teacher','teacherForm()'):''):btn('Role permissions','permissions()',''))+table(['NAME','ROLE','BRANCH','STATUS',''],list.map(p=>[`<span class="avatar">${esc((p.name||'?')[0])}</span> ${esc(p.name)}`,teacher?'Teacher':cap(p.role),esc(p.role==='owner'?'All branches':branchName()),badge('Active'),teacher?btn('View schedule',"go('Calendar')",'small'):'']))+`<div class="note" style="margin-top:16px">Team accounts are created by the academy owner. To add or remove someone, ask the owner.</div>`}
