function settings(){const b=db.branchInfo||{};return head('Academy settings','A workspace that feels like Arcko.')+`<div class="card pad"><form onsubmit="saveSettings(event)"><div class="formgrid">${field('Branch name','name',b.name||'')}${field('Contact email','email',b.email||'','email',false)}<label class="field">Brand colours<div class="actions"><span class="badge">Logo Green #80BE2C</span><span class="badge blue">Logo Blue #489CF0</span></div></label></div><div class="formfoot"><button class="primary">Save settings</button></div></form></div><div class="card pad sectiongap"><h2>Your account</h2><p class="sub" style="margin:12px 0 20px">${esc(me.name)} · ${esc(cap(me.role))}${me.role==='owner'?'':' · '+esc(branchName())}</p>${btn('Sign out',"signOut()",'danger')}</div>`}function saveSettings(e){e.preventDefault();let v=Object.fromEntries(new FormData(e.target));db.branchInfo={...db.branchInfo,name:v.name,email:v.email};save();render();toast('Settings saved')}
function operations(){if(page==='Schools & venues')return head(page,'Your places for curiosity and creation.',btn('+ Add venue',"genericForm('Schools & venues')"))+((db.extras[page]||[]).length?extraTable(page):'<div class="card empty">No venues yet. Add your first venue.</div>');if(page==='Holidays')return head(page,'Plan closures and communicate upcoming breaks.',btn('+ Add holiday',"holidayForm()"))+((db.extras['Holidays']||[]).length?extraTable(page):'<div class="card empty">No closures scheduled. Add a holiday.</div>');if(page==='Teacher payroll'){const pre=todayStr().slice(0,7);return head(page,'Teaching fees for '+new Date().toLocaleString('en-US',{month:'long',year:'numeric'})+'.',btn('Export CSV',"exportData('payroll')",''))+table(['TEACHER','LESSONS','RATE / LESSON','TOTAL',''],db.teachers.map(t=>{let n=db.lessons.filter(l=>l.teacher_id===t.id&&l.date.startsWith(pre)).length;return[esc(t.name),n,money(PAY_RATE),money(n*PAY_RATE),badge('Draft')]}))+`<div class="note">Rate: ${money(PAY_RATE)} per lesson (set PAY_RATE in data.js). This is a calculation only; no payouts are made.</div>`}return head('Recurring invoices','Set up a repeat billing template.',btn('+ Add recurring invoice',"genericForm('Recurring invoices')"))+`<div class="card empty">No recurring templates yet. Templates do not send or generate bills automatically.</div>`+extraTable(page)}
