function portal(){const t0=todayStr();const mine=db.lessons.filter(l=>l.date>=datePlus(-7));const upcoming=db.lessons.filter(l=>l.date>=t0).slice(0,3);let content='';if(portalTab==='Home')content=`<div class="welcome"><div><h2>A new day to inspire.</h2><p>Let’s make learning meaningful.</p></div></div><div class="portaltiles">${['Schedule','Attendance','Progress'].map((t,i)=>`<button onclick="portalTab='${t}';render()">${icon(['calendar','check','star'][i])}${t}</button>`).join('')}</div><h3>Next lessons</h3>${upcoming.map(l=>`<div class="todo" onclick="lessonDetail(${l.id})"><span class="branch-icon">${icon('book')}</span><div><strong>${esc(l.subject)}</strong><small>${l.date} · ${l.time}</small></div><span class="arrow">→</span></div>`).join('')||'<div class="empty">No upcoming lessons.</div>'}<div class="note">Curious. Creative. Caring.</div>`;else if(portalTab==='Schedule'||portalTab==='Attendance')content=`<h2>${portalTab}</h2>`+(mine.map(l=>`<div class="todo" onclick="lessonDetail(${l.id})"><div><strong>${esc(l.subject)}</strong><small>${l.date} · ${l.time}<br>${esc(l.room)} · ${classSize(l)} students</small></div><span class="arrow">→</span></div>`).join('')||'<div class="empty">No lessons assigned to you yet.</div>');else if(portalTab==='Progress')content=progressCards();else content='<div class="empty">No announcements.</div>';return head('My classroom','Your lessons, attendance and progress notes.')+`<div class="phone"><div class="cardhead">${brandMark()}<span class="avatar">${esc((me.name||'?')[0])}</span></div><p class="sub">Hello, ${esc(me.name)}</p><h1 style="margin:7px 0 20px">Your creative classroom</h1>${portalTab!=='Home'?btn('← Home',"portalTab='Home';render()",'link')+'<div style="height:18px"></div>':''}${content}<div class="bottomnav">${['Home','Schedule','Progress'].map((t,i)=>`<button onclick="portalTab='${t}';render()">${icon(['home','calendar','star'][i])}${t}</button>`).join('')}</div></div>`}

function render(){if(!me)return;sidebar();$('#crumb').textContent=role!=='Admin view'?'My classroom':page;let html;if(role!=='Admin view')html=portal();else switch(page){case'Dashboard':html=dashboard();break;case'Students':html=studentList();break;case'Clients':html=studentList();break;case'Student profile':html=profile();break;case'Leads':html=leads();break;case'Calendar':html=calendar();break;case'Class groups':case'Student groups':html=classGroupsPage();break;case'Lessons':html=head('Lessons','Build a thoughtful rhythm for every programme.',btn('+ Add lesson',"lessonForm()"))+filter('Search programme, teacher or venue…')+lessonTable(db.lessons.filter(matches));break;case'Packages':html=packages();break;case'Invoices & payments':html=invoices();break;case'Attendance':html=head('Attendance','Mark attendance and keep session balances in sync.')+lessonTable(db.lessons);break;case'Student progress':html=head('Student progress','Capture the thinking behind every creation.')+progressCards();break;case'Make-up requests':html=requests();break;case'Teachers':case'Personnel':html=people();break;case'Settings':html=settings();break;case'Reports':html=reports();break;case'Export data':html=exportPage();break;default:html=operations()}$('#main').innerHTML=html;syncMobileNav();updateChip()}

function openNavigation(){document.body.classList.add('menu-open');document.querySelector('#menu-toggle').setAttribute('aria-expanded','true');document.querySelector('.nav-close').focus()}
function closeNavigation(restore=true){const wasOpen=document.body.classList.contains('menu-open');document.body.classList.remove('menu-open');document.querySelector('#menu-toggle')?.setAttribute('aria-expanded','false');if(restore&&wasOpen)document.querySelector('#menu-toggle')?.focus()}
function syncMobileNav(){const el=document.querySelector('#mobile-nav');if(!el)return;el.innerHTML=role==='Admin view'?[['Dashboard','home','Home'],['Calendar','calendar','Calendar'],['Students','users','Students'],['More','settings','More']].map(([p,i,l])=>`<button class="${page===p?'active':''}" ${page===p?'aria-current="page"':''} onclick="${p==='More'?'openNavigation()':"go('"+p+"')"}">${icon(i)}<span>${l}</span></button>`).join(''):['Home','Schedule','Progress'].map((t,i)=>`<button class="${portalTab===t?'active':''}" onclick="portalTab='${t}';render()">${icon(['home','calendar','star','bell'][i])}<span>${t===t}</span></button>`).join('')}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeNavigation();if(e.key==='Tab'&&document.body.classList.contains('menu-open')){const items=[...document.querySelectorAll('#sidebar button')],first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});

function mobileAgenda(){const prefix=`${year}-${String(month+1).padStart(2,'0')}`;const ls=db.lessons.filter(l=>l.date.startsWith(prefix)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return `<div class="calendar-agenda">${ls.length?Object.entries(ls.reduce((groups,l)=>{(groups[l.date]??=[]).push(l);return groups},{})).map(([date,items])=>`<section class="agenda-day"><h3>${new Date(date+'T12:00:00').toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'short'})}</h3>${items.map(l=>`<button class="agenda-event" onclick="lessonDetail(${l.id})"><span class="agenda-time">${l.time}</span><span><strong>${esc(l.subject)}</strong><small>${esc(l.title)}</small><small>${esc(l.teacher)} · ${classSize(l)}/8 students</small></span><span class="agenda-arrow">›</span></button>`).join('')}</section>`).join(''):'<div class="empty">No lessons this month. Schedule a creative moment.</div>'}</div>`}

function teacherForm(){
 if(me.role!=='owner')return toast('Only the owner can create teacher accounts');
 modal('Add teacher','Create a teacher login for '+esc(branchName())+'. Share the password with the teacher yourself.',`<div class="formgrid">${field('Full name','name')}${field('Email','email','','email')}${field('Initial password (12+ characters)','password','','password')}</div><p id="teacher-error" role="alert"></p>`,async v=>{
  const b=$('#modalform button[type=submit]');const err=$('#teacher-error');
  if(v.password.length<12){err.textContent='Use at least 12 characters.';return}
  b.disabled=true;err.textContent='';
  try{const {data,error}=await sb.functions.invoke('add-teacher',{body:{name:v.name.trim(),email:v.email.trim(),password:v.password,branch_id:activeBranch}});if(error||data?.error)throw new Error(data?.error||'Could not create teacher. Check that add-teacher is deployed and the email is unused.');await loadAll();closeModal();render();toast('Teacher account created')}catch(e){err.textContent=e.message}finally{b.disabled=false}
 });
}
